import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    os_name = platform.system()
    if os_name == "Windows":
        cmd = ["wmic", "cpu", "get", "loadpercentage"]
    else:
        cmd = ["mpstat", "1", "1"]
    data = []
    cycles = int(duration / interval)
    for i in range(cycles):
        timestamp = time.time()
        try:
            output = subprocess.check_output(cmd).decode()
            if os_name == "Windows":
                lines = output.strip().split('\n')
                cpu_usage = float(lines[1].strip())
            else:
                lines = output.strip().split('\n')
                last_line = lines[-1]
                parts = last_line.split()
                cpu_usage = 100.0 - float(parts[-1])
        except:
            cpu_usage = 0.0
        data.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        if i < cycles - 1:
            time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(data, f)
    except IOError:
        return None
    return LOGFILE_PATH

import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    network = IPv4Network(ip_range, strict=False)
    result = {}
    for ip in network.hosts():
        try:
            response = subprocess.run(['ping', '-c', '1', '-W', '1', str(ip)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            result[str(ip)] = response.returncode == 0
        except subprocess.CalledProcessError:
            raise
    return result

def task_func(script_name='backup.sh', log_file='/home/user/backup_log.json'):
    if not os.path.exists(script_name):
        raise FileNotFoundError(f"Script file {script_name} not found")
    start_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    try:
        result = subprocess.run([script_name], shell=True, capture_output=True)
        exit_status = result.returncode
    except Exception as e:
        raise RuntimeError(f"Error executing script: {e}")
    end_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    log_data = {
        'start_time': start_time,
        'end_time': end_time,
        'exit_status': exit_status
    }
    with open(log_file, 'w') as f:
        json.dump(log_data, f)
    return log_data

